"""Write the agent graph as a Mermaid diagram to docs/agent_graph.md."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from src.agent.graph import build_agent_graph


def main():
    mermaid = build_agent_graph().get_graph().draw_mermaid()
    (ROOT / "docs" / "agent_graph.md").write_text(
        "# Agent graph\n\nGenerated by `scripts/export_agent_graph.py` from the compiled LangGraph.\n\n"
        "- `retrieve` runs hybrid retrieval (vector + graph, re-ranked) first.\n"
        "- `agent` calls the reasoning model with the tools bound; the final allowed step is made without tools.\n"
        "- `tools` runs each requested tool and returns a `ToolMessage`, then control goes back to `agent`.\n\n"
        f"```mermaid\n{mermaid}\n```\n",
        encoding="utf-8",
    )
    print("Wrote docs/agent_graph.md")


if __name__ == "__main__":
    main()
